import math
    import random
    import time

    LANGUAGE_WRAPPER = 'The numbers 1 through {n_vertices} are written uniformly at random on the vertices of the {dimension}-dimensional hypercube Q_{dimension}. Two labels are considered consecutive if they differ by 1 modulo {n_vertices}. Let p/q (in lowest terms) denote the probability that no two consecutive labels are placed on adjacent vertices of the hypercube. Find p + q.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a dimension among {3,4}. Q3 (8 vertices) recovers the seed's dual structure; Q4 (16 vertices) is significantly harder.
d = rng.choice([3, 4])
n = 1 << d
# Return assignment with placeholders required by the wrapper
return {'dimension': d, 'n_vertices': n}

    def verifier(assign):
# Validate inputs and compute the required p+q.
# The probability that no two consecutive numbers modulo n are adjacent on Q_d is computed via inclusion-exclusion over the n cyclic pairs,
# combined with counts of k-matchings in the number cycle and k-matchings in the hypercube. We then reduce the resulting rational number and return p+q.

# --- Validation ---
if not isinstance(assign, dict):
    # invalid structure
    return (False, None)  # invalid
if 'dimension' not in assign or 'n_vertices' not in assign:
    return (False, None)  # missing fields
d = assign['dimension']
n = assign['n_vertices']
if not (isinstance(d, int) and isinstance(n, int)):
    return (False, None)
if d < 3 or d > 4:
    return (False, None)  # enforce nontrivial yet computable instances
if n != (1 << d):
    return (False, None)  # must match hypercube vertex count

# --- Utility functions ---
def fact(m):
    r = 1
    for i in range(2, m+1):
        r *= i
    return r
def comb(a, b):
    if b < 0 or b > a:
        return 0
    b = min(b, a - b)
    num = 1
    den = 1
    for i in range(1, b+1):
        num *= (a - b + i)
        den *= i
    return num // den
def gcd(x, y):
    while y:
        x, y = y, x % y
    return abs(x)

# number of k-matchings in the cycle C_n of the n labels (edges are consecutive pairs modulo n)
def cycle_matchings(nv, k):
    if k < 0 or 2*k > nv:
        return 0
    if k == 0:
        return 1
    # A(C_n, k) = n/(n-k) * C(n-k, k), known formula for k-matchings in a cycle
    return (nv * comb(nv - k, k)) // (nv - k)

# Build hypercube Q_d adjacency
N = n
# adjacency list for vertices 0..N-1; neighbors differ by one bit
neighbors = [[] for _ in range(N)]
for v in range(N):
    for bit in range(d):
        u = v ^ (1 << bit)
        neighbors[v].append(u)

# DP over induced subgraphs using a vertex mask to count matchings by size.
# For a given mask S of remaining vertices, f(S)[k] = number of k-edge matchings in the induced subgraph.
from functools import lru_cache
maxK = N // 2

@lru_cache(maxsize=None)
def f(mask):
    if mask == 0:
        # no vertices: only the empty matching
        return tuple([1] + [0]*maxK)
    # pick the smallest-index remaining vertex
    v = (mask & -mask)
    v_idx = (v.bit_length() - 1)
    # Option A: leave v unmatched
    mask_without_v = mask ^ (1 << v_idx)
    A = list(f(mask_without_v))
    # Option B: match v with one available neighbor u in mask
    res = A[:]
    # For each neighbor u present, include edge (v,u)
    for u_idx in neighbors[v_idx]:
        if (mask >> u_idx) & 1:
            sub = list(f(mask_without_v ^ (1 << u_idx)))
            # shift by +1 in matching size
            for k in range(maxK-1, -1, -1):
                val = sub[k]
                if val:
                    res[k+1] += val
    return tuple(res)

# Compute M_G(k) for G = Q_d
full_mask = (1 << N) - 1
counts = list(f(full_mask))  # counts[k] = number of k-matchings in Q_d

# Inclusion-Exclusion over the set of n consecutive pairs (edges of C_n)
total_num = 0
for k in range(0, maxK+1):
    Ak = cycle_matchings(N, k)
    Mk = counts[k]
    if Mk == 0 or Ak == 0:
        continue
    term = Ak * Mk * fact(k) * (1 << k) * fact(N - 2*k)
    if k % 2 == 1:
        total_num -= term
    else:
        total_num += term
total_den = fact(N)
if total_num <= 0 or total_den <= 0:
    # Probability must be positive in these instances
    return (False, None)
g = gcd(total_num, total_den)
p = total_num // g
q = total_den // g
# Basic difficulty/nontriviality checks
if p <= 0 or q <= p:
    # extremely trivial or degenerate
    return (False, None)
return (True, p + q)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

